int hidp_setup_session(struct hidp_session *session, struct hidp_connadd_req *req) {
    int ret = -ENOMEM;
    struct hid_device *hdev = NULL;

    if (!session || !req) {
        return -EINVAL;
    }

    session->read_buf = kmalloc(req->rd_size, GFP_KERNEL);
    if (!session->read_buf) {
        goto err;
    }

    session->read_size = req->rd_size;

    hdev = hid_allocate_device();
    if (!hdev) {
        goto err;
    }

    hdev->vendor = req->vendor;
    hdev->product = req->product;
    hdev->bus = req->bus;
    hdev->version = req->version;
    hdev->country = req->country;

    if (hid_check_blacklist(hdev)) {
        ret = -ENODEV;
        goto err;
    }

    session->hid_dev = hdev;
    return 0;

err:
    kfree(session->read_buf);
    session->read_buf = NULL;
    session->read_size = 0;
    hid_destroy_device(hdev);
    return ret;
}
